import anthropic

def transfer(acct, cents, reason):
    """Transfer funds to an account using Claude with ledger tools."""
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post an amount to a ledger account with a memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the posting"
                    }
                },
                "required": ["account", "cents", "memo"]
            ]
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account {acct} with the reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    while response.stop_reason == "tool_use":
        tool_use_block = next(
            (block for block in response.content if block.type == "tool_use"),
            None
        )

        if tool_use_block and tool_use_block.name == "post":
            input_data = tool_use_block.input

            messages.append({"role": "assistant", "content": response.content})

            tool_result = f"Entry ID: {tool_use_block.id}"

            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": tool_result
                    }
                ]
            })

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )

            return tool_use_block.id

    return None
