def encode_amount(dollars: str) -> str:
    """Serialize a money amount string (e.g. '12.30', '-0.07') to the wire format.

    The wire format encodes the amount as an integer number of cents, rendered
    as a decimal string. This avoids floating point and is stable to round-trip.
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    negative = False
    if s[0] in "+-":
        negative = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        whole, _, frac = s.partition(".")
        if "." in frac:
            raise ValueError("multiple decimal points")
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit():
        raise ValueError("invalid whole part")
    if frac and not frac.isdigit():
        raise ValueError("invalid fractional part")

    # Normalize fractional part to exactly 2 digits (cents).
    if len(frac) > 2:
        raise ValueError("more than two decimal places")
    frac = (frac + "00")[:2]

    cents = int(whole) * 100 + int(frac)
    if negative and cents != 0:
        cents = -cents

    return str(cents)

def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    sign = '+'
    if s[0] == '-':
        sign = '-'
        s = s[1:]
    elif s[0] == '+':
        s = s[1:]

    if '.' in s:
        whole, frac = s.split('.', 1)
        if not whole:
            whole = '0'
        frac = (frac + '00')[:2]
        cents_str = whole + frac
    else:
        cents_str = s + '00'

    digits = str(int(cents_str))
    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

