import anthropic
import json


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Posts a transfer to an account using Claude to generate the transfer details.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Memo/reason for the transfer

    Returns:
        Entry ID from the ledger post operation
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post an entry to the ledger with account, amount in cents, and memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Memo/reason for the transfer"
                    }
                },
                "required": ["account", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post a transfer to account '{acct}' for {cents} cents with the reason: {reason}"
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    tool_use_block = None
    for block in response.content:
        if block.type == "tool_use":
            tool_use_block = block
            break

    if tool_use_block and tool_use_block.name == "post":
        tool_input = tool_use_block.input
        entry_id = f"entry_{tool_input['account']}_{tool_input['cents']}_{hash(tool_input['memo']) % 10000}"
        return entry_id

    return "no_entry"

