    # Encode amount as per team invariant: sign + absolute digits + "#" + check digit
    if cents < 0:
        sign = "-"
        digits = str(-cents)
    else:
        sign = "+"
        digits = str(cents)
    digit_sum = sum(int(d) for d in digits)
