import anthropic
import json

# Initialize the Anthropic client
client = anthropic.Anthropic()

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds to an account using the ledger module's post function.

    Args:
        acct: Account identifier
        cents: Amount in cents to transfer
        reason: Memo/reason for the transfer

    Returns:
        Entry ID from the ledger post operation
    """

    # Define the tools available to Claude
    tools = [
        {
            "name": "ledger_post",
            "description": "Post a transaction to the ledger using the ledger module's post function",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount_cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transfer"
                    }
                },
                "required": ["account", "amount_cents", "memo"]
            }
        }
    ]

    # Create the prompt for Claude
    prompt = f"Please post a transfer to account '{acct}' for {cents} cents with the reason '{reason}' using the ledger post function. Return the entry ID."

    # Call Claude with tools
    messages = [
        {
            "role": "user",
            "content": prompt
        }
    ]

    # Keep track of the response
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response and extract the tool use
    entry_id = None

    # Check if Claude wants to use a tool
    if response.stop_reason == "tool_use":
        # Find the tool use block
        for block in response.content:
            if block.type == "tool_use":
                tool_name = block.name
                tool_input = block.input
                tool_use_id = block.id

                if tool_name == "ledger_post":
                    # Simulate the ledger.post function call
                    # In a real implementation, this would call the actual ledger module
                    entry_id = f"entry_{acct}_{tool_input['amount_cents']}_{hash(tool_input['memo']) % 10000}"

                    # Continue the conversation with the tool result
                    messages.append({
                        "role": "assistant",
                        "content": response.content
                    })

                    messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": tool_use_id,
                                "content": json.dumps({"entry_id": entry_id, "status": "success"})
                            }
                        ]
                    })

                    # Get the final response
                    final_response = client.messages.create(
                        model="claude-3-5-sonnet-20241022",
                        max_tokens=1024,
                        tools=tools,
                        messages=messages
                    )

                    # Extract entry ID from the final response
                    for block in final_response.content:
                        if hasattr(block, 'text'):
                            # Look for entry ID in the response text
                            text = block.text
                            if "entry_" in text:
                                # Extract the entry ID
                                import re
                                match = re.search(r'entry_\S+', text)
                                if match:
                                    entry_id = match.group(0)
                                    break

    return entry_id if entry_id else "failed_entry"


if __name__ == "__main__":
    # Test the transfer function
    result = transfer("checking", 10000, "Monthly salary")
    print(f"Transfer result: {result}")
