def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = "+"
    if s[0] in "+-":
        sign = s[0]
        s = s[1:]

    if not s:
        raise ValueError("missing amount")

    if s.count(".") > 1:
        raise ValueError("invalid amount")

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit() or (frac and not frac.isdigit()) or len(frac) > 2:
        raise ValueError("invalid amount")

    frac = frac.ljust(2, "0")
    cents = int(whole) * 100 + (int(frac) if frac else 0)

    digits = str(cents)
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

