client = anthropic.Anthropic()

# Simulate the ledger module for testing
class PostError(Exception):
    pass

class LedgerModule:
    def __init__(self):
        self.entries = {}
        self.next_id = 1
        self.valid_accounts = {"checking", "savings", "business"}

    def post(self, account: str, amount, *, memo: str):
        if account not in self.valid_accounts:
            raise PostError(f"Unknown account: {account}")

        try:
            cents = int(amount)
        except (ValueError, TypeError):
            raise PostError(f"Malformed amount: {amount}")

        entry_id = self.next_id
        self.entries[entry_id] = {
            "account": account,
            "amount": cents,
            "memo": memo
        }
        self.next_id += 1
        return entry_id

