    # strip optional sign, preserving it
    s = dollars.strip()
    if s.startswith('+'):
        s = s[1:]
    negative = s.startswith('-')
    if negative:
        s = s[1:]
    if '.' not in s:
        s += '.00'
    integer_part, frac_part = s.split('.', 1)
    if len(frac_part) != 2:
        frac_part = (frac_part + '00')[:2]
    integer_part = integer_part.lstrip('0') or '0'
    formatted = integer_part + '.' + frac_part
    if negative:
        formatted = '-' + formatted
    return formatted

