import anthropic
import json

client = anthropic.Anthropic()
MODEL_NAME = "claude-3-5-sonnet-20241022"

# Define the ledger tools
tools = [
    {
        "name": "post",
        "description": "Post an entry to the ledger. Returns the entry id.",
        "input_schema": {
            "type": "object",
            "properties": {
                "account": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents to post"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo/reason for the entry"
                }
            },
            "required": ["account", "cents", "memo"]
        }
    }
]

def transfer(acct, cents, reason):
    """Transfer cents to account acct using reason as the memo, returns the entry id."""

    # Create the user message
    user_message = f"""Using the ledger post function, post {cents} cents to account "{acct}" with memo "{reason}". 
    Return the entry id that is returned by the post function."""

    messages = [
        {"role": "user", "content": user_message}
    ]

    # Make the API call
    response = client.messages.create(
        model=MODEL_NAME,
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    while response.stop_reason == "tool_use":
        tool_use = next(block for block in response.content if block.type == "tool_use")
        tool_name = tool_use.name
        tool_input = tool_use.input

        # Simulate the ledger.post function
        entry_id = f"entry_{acct}_{cents}_{hash(reason) & 0xFFFFFF:06x}"

        tool_result = {
            "type": "tool_result",
            "tool_use_id": tool_use.id,
            "content": entry_id
        }

        # Continue the conversation with the tool result
        messages = [
            {"role": "user", "content": user_message},
            {"role": "assistant", "content": response.content},
            {"role": "user", "content": [tool_result]}
        ]

        response = client.messages.create(
            model=MODEL_NAME,
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

    # Extract the entry id from the final response
    final_response = next(
        (block.text for block in response.content if hasattr(block, "text")),
        None
    )

    if final_response:
        # Parse the entry id from the response
        import re
        match = re.search(r'entry_\w+_\d+_\w+', final_response)
        if match:
            return match.group()
        # Try to extract any id-like string
        words = final_response.split()
        for word in words:
            if 'entry' in word.lower() or len(word) > 10:
                return word.strip('.,;:!?"\'')

    return entry_id

