def encode_amount(dollars: str) -> str:
    """Serialize a money amount string to team-private wire format."""
    amount = dollars.strip()
    if not amount:
        raise ValueError("empty amount string")

    negative = False
    if amount.startswith('-'):
        negative = True
        amount = amount[1:]
    elif amount.startswith('+'):
        amount = amount[1:]

    num = amount
    if '.' in num:
        parts = num.split('.')
        if len(parts) != 2:
            raise ValueError(f"invalid amount: {dollars}")
        integer_part, frac_part = parts
        if not integer_part:
            integer_part = '0'
    else:
        integer_part = num
        frac_part = ''

    if not integer_part.isdigit():
        raise ValueError(f"invalid integer part: {dollars}")

    if len(frac_part) > 2:
        # truncate to two decimals
        frac_part = frac_part[:2]
    if len(frac_part) < 2:
        frac_part = frac_part.ljust(2, '0')
    if not frac_part.isdigit():
        raise ValueError(f"invalid fractional part: {dollars}")

    # remove leading zeros from integer part but keep at least one digit
    integer_part = integer_part.lstrip('0') or '0'

    wire = f"{integer_part}.{frac_part}"
    if negative:
        wire = '-' + wire
    return wire

