import anthropic

def transfer(acct: str, cents: int, reason: str) -> str:
    """Transfer cents to account using reason as memo and return entry id."""
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts an amount to an account with a memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo/reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with reason '{reason}' and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process tool use
    if response.stop_reason == "tool_use":
        for content_block in response.content:
            if content_block.type == "tool_use":
                # Simulate the post function call
                tool_input = content_block.input
                # Return a mock entry id based on the parameters
                entry_id = f"entry_{hash((tool_input['account'], tool_input['amount'], tool_input['memo'])) % 10000000}"
                return entry_id

    # If no tool was called, return a default entry id
    return f"entry_{hash((acct, cents, reason)) % 10000000}"
