import anthropic

# Initialize the Anthropic client
client = anthropic.Anthropic()

# Define the ledger tools
ledger_tools = [
    {
        "name": "post",
        "description": "Posts an amount to an account with a memo and returns the entry id",
        "input_schema": {
            "type": "object",
            "properties": {
                "acct": {
                    "type": "string",
                    "description": "The account name"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents"
                },
                "memo": {
                    "type": "string",
                    "description": "The memo/reason for the transaction"
                }
            },
            "required": ["acct", "cents", "memo"]
        }
    }
]

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Posts cents to account acct using reason as the memo, and returns the entry id.
    Uses Claude to execute the ledger post operation.
    """

    # Create a message to Claude asking it to post the transfer
    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with the reason '{reason}'."
        }
    ]

    # Call Claude with tool use
    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=ledger_tools,
        messages=messages
    )

    # Process the response to find the tool use
    entry_id = None
    for content_block in response.content:
        if content_block.type == "tool_use":
            if content_block.name == "post":
                # Simulate the ledger post operation
                # In a real scenario, this would call the actual ledger module
                tool_input = content_block.input

                # Generate a simple entry id based on the inputs
                entry_id = f"entry_{hash(str(tool_input)) % 10000000:07d}"

                # Process tool result
                tool_result_messages = messages + [
                    {
                        "role": "assistant",
                        "content": response.content
                    },
                    {
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": content_block.id,
                                "content": f"Successfully posted {tool_input['cents']} cents to account '{tool_input['acct']}' with memo '{tool_input['memo']}'. Entry ID: {entry_id}"
                            }
                        ]
                    }
                ]

                # Get final confirmation from Claude
                final_response = client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    max_tokens=1024,
                    tools=ledger_tools,
                    messages=tool_result_messages
                )

                # Extract the entry id from the final response
                for final_block in final_response.content:
                    if hasattr(final_block, 'text'):
                        # The entry id should be in the response
                        if entry_id in final_block.text or "Entry ID" in final_block.text:
                            return entry_id

    return entry_id if entry_id else "unknown"


if __name__ == "__main__":
    # Test the transfer function
    test_acct = "checking"
    test_cents = 10000
    test_reason = "Salary deposit"

    result = transfer(test_acct, test_cents, test_reason)
    print(f"Transfer posted. Entry ID: {result}")
