def encode_amount(dollars: str) -> str:
    """Serialize a money amount (e.g. '12.30', '-0.07') to the team's private wire format."""
    # Validate and parse the input string
    if not dollars:
        raise ValueError("empty amount string")

    # Determine sign
    sign = ""
    if dollars[0] == '-':
        sign = "-"
        dollars = dollars[1:]
    elif dollars[0] == '+':
        dollars = dollars[1:]

    if not dollars:
        raise ValueError("amount string missing value")

    # Split into integer and fractional parts
    if '.' in dollars:
        int_part, frac_part = dollars.split('.', 1)
        if not int_part and not frac_part:
            raise ValueError("amount string is just a dot")
    else:
        int_part = dollars
        frac_part = ""

    # Validate integer part (optional, can be empty like ".34" -> "0.34")
    if int_part:
        if not int_part.isdigit():
            raise ValueError("invalid characters in integer part")
    else:
        int_part = "0"

    # Pad or truncate fractional part to exactly 2 decimal places
    if len(frac_part) == 0:
        frac_part = "00"
    elif len(frac_part) == 1:
        frac_part = frac_part + "0"
    elif len(frac_part) >= 3:
        frac_part = frac_part[:2]

    if not frac_part.isdigit():
        raise ValueError("invalid characters in fractional part")

    # Remove leading zeros from integer part (except keep one if it's exactly "0")
    int_part = int_part.lstrip('0')
    if not int_part:
        int_part = "0"

    # Wire format: sign, integer dollars, ":", two-digit cents
    # Example: "12.30" -> "12:30", "-0.07" -> "-0:07"
    return f"{sign}{int_part}:{frac_part}"

