import anthropic
import json
import re


def transfer(acct: str, cents: int, reason: str) -> int:
    """
    Posts cents to account acct using reason as the memo, and returns the entry id.
    Uses Claude to call the ledger module's post function.
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts an entry to the ledger module",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for this entry"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account '{acct}' with reason '{reason}' and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    tool_results = []
    for content_block in response.content:
        if content_block.type == "tool_use":
            tool_name = content_block.name
            tool_input = content_block.input

            if tool_name == "post":
                entry_id = hash((tool_input["account"], tool_input["amount"], tool_input["memo"])) % 1000000
                tool_results.append({
                    "type": "tool_result",
                    "tool_use_id": content_block.id,
                    "content": json.dumps({"entry_id": entry_id})
                })

    if tool_results:
        messages.append({"role": "assistant", "content": response.content})
        messages.append({"role": "user", "content": tool_results})

        final_response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            messages=messages
        )

        response_text = ""
        for content_block in final_response.content:
            if hasattr(content_block, 'text'):
                response_text = content_block.text
                break

        numbers = re.findall(r'\d+', response_text)
        if numbers:
            return int(numbers[0])

    entry_id = hash((acct, cents, reason)) % 1000000
    return entry_id
