def encode_amount(dollars: str) -> str:
    """Serialize a money amount (e.g. '12.30', '-0.07') to the wire format.

    The wire format encodes the amount as an integer number of cents,
    represented as a decimal string (sign preserved, no leading zeros
    beyond a single '0', no decimal point).
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    neg = False
    if s[0] in "+-":
        neg = s[0] == "-"
        s = s[1:]

    if not s:
        raise ValueError("malformed amount")

    if "." in s:
        whole, _, frac = s.partition(".")
        if "." in frac:
            raise ValueError("malformed amount")
    else:
        whole, frac = s, ""

    whole = whole or "0"

    if not whole.isdigit():
        raise ValueError("malformed amount")
    if frac and not frac.isdigit():
        raise ValueError("malformed amount")

    # normalize fractional part to exactly 2 digits (cents)
    if len(frac) > 2:
        raise ValueError("too many fractional digits")
    frac = (frac + "00")[:2]

    cents = int(whole) * 100 + int(frac)

    if neg and cents != 0:
        return "-" + str(cents)
    return str(cents)

