import anthropic
import json


def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds using the ledger module's post function.

    Args:
        acct: The account to transfer to
        cents: The amount in cents
        reason: The memo/reason for the transfer

    Returns:
        The entry id from the ledger post
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with the reason '{reason}' and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response to extract the tool use
    while response.stop_reason == "tool_use":
        # Find the tool use block
        tool_use_block = None
        for block in response.content:
            if block.type == "tool_use":
                tool_use_block = block
                break

        if not tool_use_block:
            break

        # Simulate the tool call - in a real scenario, this would call the actual ledger module
        tool_name = tool_use_block.name
        tool_input = tool_use_block.input

        # For simulation purposes, we'll return a mock entry ID
        # In a real implementation, this would call: ledger.post(account=tool_input["account"], amount=tool_input["amount"], memo=tool_input["memo"])
        if tool_name == "post":
            entry_id = f"entry_{acct}_{cents}_{hash(reason) % 10000}"

            # Add the assistant's response and tool result to messages
            messages.append({"role": "assistant", "content": response.content})
            messages.append({
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_use_block.id,
                        "content": json.dumps({"entry_id": entry_id})
                    }
                ]
            })

            # Get the next response
            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages
            )
        else:
            break

    # Extract the entry ID from the final response
    for block in response.content:
        if hasattr(block, 'text'):
            # Try to find entry ID in the text response
            text = block.text
            if "entry_" in text:
                # Extract the entry ID
                import re
                match = re.search(r'entry_\w+', text)
                if match:
                    return match.group(0)

    # Return the mock entry ID we created
    return f"entry_{acct}_{cents}_{hash(reason) % 10000}"


if __name__ == "__main__":
    # Example usage
    entry_id = transfer("savings", 5000, "Monthly transfer")
    print(f"Transfer posted with entry ID: {entry_id}")
