import re

def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise ValueError("Amount must be a string")

    stripped = dollars.strip()
    if not stripped:
        raise ValueError("Amount string must not be empty")

    # Check that the string only contains valid characters: digits, optional leading minus, one decimal point
    if not re.match(r'^-?\d+\.\d{2}$', stripped):
        raise ValueError(f"Invalid amount format: {dollars!r}")

    try:
        value = Decimal(stripped)
    except InvalidOperation:
        raise ValueError(f"Invalid decimal value: {dollars!r}")

    # Enforce exactly 2 decimal places (already guaranteed by regex, but keep for safety)
    if value.as_tuple().exponent != -2:
        raise ValueError("Amount must have exactly 2 decimal places")

    sign = 0 if value >= 0 else 1
    abs_value = abs(value)
    dollars_part = int(abs_value)
    cents_part = int((abs_value - dollars_part) * 100)

    return f"@{sign}${dollars_part:08d}#{cents_part:02d}c"

