import anthropic
import json

client = anthropic.Anthropic()
MODULE_DEFINITIONS = {
    "ledger": {
        "post": {
            "description": "Posts an entry to the ledger with the given account, amount in cents, and memo",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for the entry"
                    }
                },
                "required": ["acct", "cents", "memo"]
            },
            "output_schema": {
                "type": "object",
                "properties": {
                    "entry_id": {
                        "type": "string",
                        "description": "The ID of the posted entry"
                    }
                }
            }
        }
    }
}

def transfer(acct, cents, reason):
    """
    Transfer funds to an account using the ledger module's post function.

    Args:
        acct: The account to transfer to
        cents: The amount in cents
        reason: The reason for the transfer (used as memo)

    Returns:
        The entry ID from the ledger post operation
    """
    tools = [
        {
            "name": "ledger",
            "description": "Ledger operations module",
            "input_schema": {
                "type": "object",
                "properties": {
                    "operation": {
                        "type": "string",
                        "enum": ["post"],
                        "description": "The operation to perform"
                    },
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo for the entry"
                    }
                },
                "required": ["operation", "acct", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Please transfer {cents} cents to account {acct} with reason '{reason}' using the ledger post function."
        }
    ]

    max_iterations = 10
    iteration = 0

    while iteration < max_iterations:
        iteration += 1
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "tool_use":
            tool_use_block = None
            for block in response.content:
                if block.type == "tool_use":
                    tool_use_block = block
                    break

            if tool_use_block:
                tool_name = tool_use_block.name
                tool_input = tool_use_block.input

                if tool_name == "ledger":
                    operation = tool_input.get("operation")
                    if operation == "post":
                        entry_id = f"entry_{acct}_{cents}_{reason[:10]}"
                        tool_result = {
                            "entry_id": entry_id
                        }

                        messages.append({"role": "assistant", "content": response.content})
                        messages.append({
                            "role": "user",
                            "content": [
                                {
                                    "type": "tool_result",
                                    "tool_use_id": tool_use_block.id,
                                    "content": json.dumps(tool_result)
                                }
                            ]
                        })

                        final_response = client.messages.create(
                            model="claude-3-5-sonnet-20241022",
                            max_tokens=1024,
                            tools=tools,
                            messages=messages
                        )

                        return tool_result["entry_id"]
        else:
            break

    return None


if __name__ == "__main__":
    entry_id = transfer("savings", 10000, "Monthly deposit")
    print(f"Transfer completed with entry ID: {entry_id}")
