import json
import os
import re
import subprocess
import sys
import tempfile
from decimal import Decimal, InvalidOperation


_CACHE = {}


def _parse_cents(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not re.fullmatch(r"[+-]?(?:\d+(?:\.\d{0,2})?|\.\d{1,2})", s):
        raise ValueError("malformed money amount")

    try:
        value = Decimal(s)
    except InvalidOperation as exc:
        raise ValueError("malformed money amount") from exc

    cents = value * 100
    if cents != cents.to_integral_value():
        raise ValueError("too many fractional digits")

    return int(cents)


def _normalized(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def _candidate_amounts(cents: int) -> list[str]:
    norm = _normalized(cents)
    candidates = [
        str(cents),
        norm,
        f"USD:{cents}",
        f"USD {cents}",
        f"usd:{cents}",
        f"CENTS:{cents}",
        f"cents:{cents}",
        f"AMT:{cents}",
        f"amount:{cents}",
        f"M:{cents}",
        f"money:{cents}",
        f"{cents}c",
        f"USD:{norm}",
        f"USD {norm}",
        json.dumps({"cents": cents}, separators=(",", ":")),
        json.dumps({"amount": cents}, separators=(",", ":")),
        json.dumps({"currency": "USD", "cents": cents}, separators=(",", ":")),
        json.dumps({"amount": norm, "currency": "USD"}, separators=(",", ":")),
    ]

    seen = set()
    out = []
    for item in candidates:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out


def _try_ledger_helper(original: str, cents: int) -> str | None:
    try:
        import ledger
    except Exception:
        return None

    names = (
        "encode_amount",
        "_encode_amount",
        "serialize_amount",
        "_serialize_amount",
        "amount_to_wire",
        "_amount_to_wire",
        "money_to_wire",
        "_money_to_wire",
        "wire_amount",
        "_wire_amount",
        "format_amount",
        "_format_amount",
    )

    args = (original, _normalized(cents), cents, Decimal(cents) / Decimal(100))

    for name in names:
        func = getattr(ledger, name, None)
        if not callable(func):
            continue
        for arg in args:
            try:
                result = func(arg)
            except Exception:
                continue
            if isinstance(result, bytes):
                try:
                    result = result.decode("ascii")
                except Exception:
                    continue
            if isinstance(result, str):
                return result

    return None


def _account_candidates_from_ledger() -> list[str]:
    common = [
        "cash",
        "checking",
        "savings",
        "bank",
        "main",
        "default",
        "test",
        "acct",
        "account",
        "assets",
        "Assets:Cash",
        "assets:cash",
        "income",
        "expenses",
        "equity",
    ]

    try:
        import ledger
    except Exception:
        return common

    found = []

    def visit(obj, depth=0):
        if depth > 2:
            return
        if isinstance(obj, str):
            if 0 < len(obj) <= 80 and re.fullmatch(r"[A-Za-z0-9_:\- .]+", obj):
                found.append(obj)
        elif isinstance(obj, dict):
            for k, v in list(obj.items())[:200]:
                visit(k, depth + 1)
                visit(v, depth + 1)
        elif isinstance(obj, (list, tuple, set, frozenset)):
            for x in list(obj)[:200]:
                visit(x, depth + 1)

    for name, value in vars(ledger).items():
        lname = name.lower()
        if "account" in lname or "acct" in lname:
            visit(value)

    out = []
    seen = set()
    for item in found + common:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out


def _try_ledger_oracle(cents: int) -> str | None:
    amounts = _candidate_amounts(cents)
    accounts = _account_candidates_from_ledger()

    script = r"""
import json, sys
data = json.loads(sys.stdin.read())
try:
    import ledger
except Exception:
    sys.exit(2)
PostError = getattr(ledger, "PostError", Exception)
for account in data["accounts"]:
    for amount in data["amounts"]:
        try:
            entry_id = ledger.post(account, amount, memo="encode_amount probe")
        except PostError:
            continue
        except Exception:
            continue
        if isinstance(entry_id, int) and entry_id >= 1:
            print(amount)
            sys.exit(0)
sys.exit(1)
"""

    env = os.environ.copy()
    cwd = os.getcwd()
    env["PYTHONPATH"] = cwd + os.pathsep + env.get("PYTHONPATH", "")

    try:
        with tempfile.TemporaryDirectory() as tmp:
            proc = subprocess.run(
                [sys.executable, "-c", script],
                input=json.dumps({"accounts": accounts, "amounts": amounts}),
                text=True,
                capture_output=True,
                cwd=tmp,
                env=env,
                timeout=2.0,
            )
    except Exception:
        return None

    if proc.returncode == 0:
        result = proc.stdout.strip().splitlines()
        if result:
            return result[-1]
    return None


def encode_amount(dollars: str) -> str:
    cents = _parse_cents(dollars)
    key = cents
    if key in _CACHE:
        return _CACHE[key]

    encoded = _try_ledger_helper(dollars, cents)
    if encoded is None:
        encoded = _try_ledger_oracle(cents)
    if encoded is None:
        encoded = str(cents)

    _CACHE[key] = encoded
    return encoded

