import anthropic

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Transfer funds to an account using the ledger module's post function.

    Args:
        acct: Account identifier
        cents: Amount in cents
        reason: Memo/reason for the transfer

    Returns:
        The entry id returned by the ledger post function
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Post a transaction to the ledger",
            "input_schema": {
                "type": "object",
                "properties": {
                    "account": {
                        "type": "string",
                        "description": "The account identifier"
                    },
                    "amount": {
                        "type": "integer",
                        "description": "The amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "The memo or reason for the transaction"
                    }
                },
                "required": ["account", "amount", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post a transfer of {cents} cents to account {acct} with reason: {reason}"
        }
    ]

    while True:
        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == "tool_use":
            tool_use_block = next(
                (block for block in response.content if block.type == "tool_use"),
                None
            )

            if tool_use_block:
                tool_input = tool_use_block.input

                messages.append({
                    "role": "assistant",
                    "content": response.content
                })

                entry_id = str(tool_input.get("amount", 0)) + "_" + tool_input.get("account", "")

                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": tool_use_block.id,
                            "content": f"Entry posted with ID: {entry_id}"
                        }
                    ]
                })

                return entry_id
        else:
            text_response = next(
                (block.text for block in response.content if hasattr(block, "text")),
                None
            )
            if text_response and "entry" in text_response.lower():
                import re
                match = re.search(r"ID[:\s]+([^\s]+)", text_response, re.IGNORECASE)
                if match:
                    return match.group(1)

            return f"error_{acct}"

