def encode_amount(dollars: str) -> str:
    """Serialize a money amount string (e.g. '12.30', '-0.07') to the
    team's private wire format.

    The wire format encodes the amount as a signed integer count of cents,
    rendered as a decimal string. This avoids any floating-point
    representation issues and gives an unambiguous canonical form.
    """
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    sign = ""
    if s[0] in "+-":
        if s[0] == "-":
            sign = "-"
        s = s[1:]

    if not s:
        raise ValueError("missing digits")

    if "." in s:
        whole, _, frac = s.partition(".")
        if "." in frac:
            raise ValueError("multiple decimal points")
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    if not whole.isdigit():
        raise ValueError("invalid whole part")
    if frac != "" and not frac.isdigit():
        raise ValueError("invalid fractional part")

    # Normalize fractional part to exactly 2 digits (cents).
    if len(frac) > 2:
        # Reject sub-cent precision rather than silently truncating.
        if any(ch != "0" for ch in frac[2:]):
            raise ValueError("sub-cent precision not allowed")
        frac = frac[:2]
    frac = (frac + "00")[:2]

    cents = int(whole) * 100 + int(frac)

    if cents == 0:
        sign = ""

    return f"{sign}{cents}"

