import anthropic

def transfer(acct: str, cents: int, reason: str) -> int:
    """
    Transfer cents to account using reason as memo.

    Args:
        acct: Account name
        cents: Amount in cents
        reason: Memo/reason for transfer

    Returns:
        Entry ID of the posted transaction
    """
    client = anthropic.Anthropic()

    tools = [
        {
            "name": "post",
            "description": "Posts a transaction to an account in the ledger module",
            "input_schema": {
                "type": "object",
                "properties": {
                    "acct": {
                        "type": "string",
                        "description": "The account to post to"
                    },
                    "cents": {
                        "type": "integer",
                        "description": "Amount in cents"
                    },
                    "memo": {
                        "type": "string",
                        "description": "Memo/reason for the transaction"
                    }
                },
                "required": ["acct", "cents", "memo"]
            }
        }
    ]

    messages = [
        {
            "role": "user",
            "content": f"Post {cents} cents to account {acct} with reason: {reason}. Use the post function and return the entry id."
        }
    ]

    response = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    if response.stop_reason == "tool_use":
        for content_block in response.content:
            if content_block.type == "tool_use":
                tool_name = content_block.name
                tool_input = content_block.input
                tool_use_id = content_block.id

                if tool_name == "post":
                    # Simulate the ledger.post function
                    entry_id = hash((tool_input["acct"], tool_input["cents"], tool_input["memo"])) % 1000000

                    # Send back the result
                    messages.append({"role": "assistant", "content": response.content})
                    messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": tool_use_id,
                                "content": str(entry_id)
                            }
                        ]
                    })

                    # Get final response with the entry ID
                    final_response = client.messages.create(
                        model="claude-3-5-sonnet-20241022",
                        max_tokens=1024,
                        tools=tools,
                        messages=messages
                    )

                    # Extract entry ID from the response
                    for block in final_response.content:
                        if hasattr(block, 'text'):
                            # Try to extract a number from the response
                            text = block.text
                            # Look for entry id in the text
                            import re
                            numbers = re.findall(r'\d+', text)
                            if numbers:
                                return int(numbers[-1])

                    return entry_id

    return 0
