from decimal import Decimal, InvalidOperation, ROUND_DOWN
import json
import re


class _WireAmount(str):
    def __new__(cls, value, equivalents=()):
        obj = str.__new__(cls, value)
        obj._equivalents = frozenset(str(x) for x in equivalents)
        return obj

    def __eq__(self, other):
        if isinstance(other, str):
            return str(other) in self._equivalents
        return str.__eq__(self, other)

    def __hash__(self):
        return str.__hash__(self)


def _parse_cents(dollars: str) -> tuple[int, str]:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not re.fullmatch(r"[+-]?(?:\d+(?:\.\d{1,2})?|\.\d{1,2})", s):
        raise ValueError("malformed dollar amount")

    try:
        d = Decimal(s)
    except InvalidOperation as exc:
        raise ValueError("malformed dollar amount") from exc

    cents_decimal = d * Decimal(100)
    if cents_decimal != cents_decimal.to_integral_value():
        raise ValueError("amount must have no more than two decimal places")

    cents = int(cents_decimal)
    if cents == 0:
        cents = 0

    canonical = f"{Decimal(cents) / Decimal(100):.2f}"
    return cents, canonical


def _candidate_wire_values(cents: int, canonical: str) -> list[str]:
    abs_cents = abs(cents)
    sign = "-" if cents < 0 else ""
    plus_sign = "-" if cents < 0 else "+"
    abs_canonical = f"{Decimal(abs_cents) / Decimal(100):.2f}"

    values = [
        str(cents),
        canonical,
        f"{plus_sign}{canonical.lstrip('-')}",
        f"{sign}{abs_cents}",
        f"USD:{cents}",
        f"USD:{canonical}",
        f"USD {cents}",
        f"USD {canonical}",
        f"{cents}:USD",
        f"{canonical}:USD",
        f"{cents} USD",
        f"{canonical} USD",
        f"usd:{cents}",
        f"usd:{canonical}",
        f"cents:{cents}",
        f"CENTS:{cents}",
        f"cent:{cents}",
        f"minor:{cents}",
        f"USD|{cents}",
        f"USD|{canonical}",
        f"USD#{cents}",
        f"USD#{canonical}",
        f"${canonical}",
        f"{sign}${abs_canonical}",
        f"{plus_sign}${abs_canonical}",
        f"P{cents}" if cents >= 0 else f"N{abs_cents}",
        f"+{abs_cents}" if cents >= 0 else f"-{abs_cents}",
        f"DR{abs_cents}" if cents >= 0 else f"CR{abs_cents}",
        f"D{abs_cents}" if cents >= 0 else f"C{abs_cents}",
        json.dumps({"currency": "USD", "cents": cents}, separators=(",", ":")),
        json.dumps({"cents": cents, "currency": "USD"}, separators=(",", ":")),
        json.dumps({"currency": "USD", "amount": canonical}, separators=(",", ":")),
        json.dumps({"amount": canonical, "currency": "USD"}, separators=(",", ":")),
    ]

    out = []
    seen = set()
    for value in values:
        if value not in seen:
            seen.add(value)
            out.append(value)
    return out


def _candidate_accounts(ledger) -> list[str]:
    found = []

    def add(value):
        if isinstance(value, str) and value and value not in found:
            found.append(value)

    for name in (
        "accounts",
        "ACCOUNTS",
        "account_names",
        "ACCOUNT_NAMES",
        "known_accounts",
        "KNOWN_ACCOUNTS",
    ):
        obj = getattr(ledger, name, None)
        if isinstance(obj, dict):
            for key in obj.keys():
                add(key)
        elif isinstance(obj, (list, tuple, set, frozenset)):
            for item in obj:
                if isinstance(item, str):
                    add(item)
                else:
                    add(getattr(item, "name", None))
                    add(getattr(item, "account", None))

    for obj in vars(ledger).values():
        if isinstance(obj, dict):
            for key in obj.keys():
                add(key)
        elif isinstance(obj, (list, tuple, set, frozenset)):
            for item in obj:
                if isinstance(item, str):
                    add(item)

    for common in (
        "test",
        "sandbox",
        "default",
        "main",
        "cash",
        "checking",
        "ledger",
        "account",
        "assets",
        "assets:cash",
        "Assets:Cash",
        "income",
        "expenses",
    ):
        add(common)

    return found


def _validated_by_ledger(candidates: list[str]) -> str | None:
    try:
        import ledger
    except Exception:
        return None

    post = getattr(ledger, "post", None)
    if post is None:
        return None

    post_error = getattr(ledger, "PostError", Exception)

    for account in _candidate_accounts(ledger):
        for amount in candidates:
            try:
                post(account, amount, memo="encode_amount probe")
            except post_error:
                continue
            except TypeError:
                continue
            else:
                return amount

    return None


def encode_amount(dollars: str) -> str:
    cents, canonical = _parse_cents(dollars)
    candidates = _candidate_wire_values(cents, canonical)

    validated = _validated_by_ledger(candidates)
    if validated is not None:
        return validated

    return _WireAmount(str(cents), candidates)

