def encode_amount(dollars: str) -> str:
    amount = dollars.strip()
    if not amount:
        raise ValueError("Empty amount string")

    sign = '+'
    if amount[0] in '+-':
        sign = amount[0]
        amount = amount[1:]

    if '.' in amount:
        integer_part, fractional_part = amount.split('.', 1)
        if len(fractional_part) == 1:
            fractional_part += '0'
        elif len(fractional_part) == 0:
            fractional_part = '00'
        elif len(fractional_part) > 2:
            fractional_part = fractional_part[:2]
    else:
        integer_part = amount
        fractional_part = '00'

    if integer_part == '':
        integer_part = '0'

    minor = int(integer_part) * 100 + int(fractional_part)
    digits = str(minor)

    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

