from decimal import Decimal, InvalidOperation


def encode_amount(dollars: str) -> str:
    """
    Encode a dollar amount string as integer cents in the ledger wire format.

    Examples:
        "12.30" -> "1230"
        "-0.07" -> "-7"
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    try:
        amount = Decimal(s)
    except InvalidOperation as exc:
        raise ValueError("malformed amount") from exc

    if not amount.is_finite():
        raise ValueError("malformed amount")

    cents = amount * 100
    if cents != cents.to_integral_value():
        raise ValueError("amount must not have more than two decimal places")

    cents_int = int(cents)
    return str(cents_int)

