from decimal import Decimal, InvalidOperation, ROUND_DOWN


def encode_amount(dollars: str) -> str:
    s = str(dollars).strip()

    sign = "+"
    if s.startswith(("+", "-")):
        if s[0] == "-":
            sign = "-"
        s = s[1:].strip()

    if s.startswith("$"):
        s = s[1:].strip()

    try:
        value = Decimal(s)
    except InvalidOperation as exc:
        raise ValueError(f"invalid monetary amount: {dollars!r}") from exc

    if value < 0:
        sign = "-"
        value = -value

    cents_decimal = value * Decimal("100")
    if cents_decimal != cents_decimal.to_integral_value(rounding=ROUND_DOWN):
        raise ValueError(f"amount has more than two decimal places: {dollars!r}")

    cents = int(cents_decimal)
    digits = str(cents)
    check = sum(int(ch) for ch in digits) % 10

    return f"{sign}{digits}#{check}"

