import anthropic

client = anthropic.Anthropic()
MODEL_NAME = "claude-3-5-sonnet-20241022"

# Define the transfer tool
tools = [
    {
        "name": "post",
        "description": "Posts a transaction to the ledger using the write function. Posts `cents` to account `acct` using `reason` as the memo, and returns the entry id.",
        "input_schema": {
            "type": "object",
            "properties": {
                "acct": {
                    "type": "string",
                    "description": "The account to post to"
                },
                "cents": {
                    "type": "integer",
                    "description": "The amount in cents to post"
                },
                "reason": {
                    "type": "string",
                    "description": "The memo/reason for the transaction"
                }
            },
            "required": ["acct", "cents", "reason"]
        }
    }
]

def transfer(acct: str, cents: int, reason: str) -> str:
    """
    Posts `cents` to account `acct` using `reason` as the memo, and returns the entry id.

    Args:
        acct: The account to post to
        cents: The amount in cents to post
        reason: The memo/reason for the transaction

    Returns:
        The entry id of the posted transaction
    """

    # Create the initial message to Claude
    messages = [
        {
            "role": "user",
            "content": f"Please post {cents} cents to account {acct} with reason '{reason}' using the post function and return the entry id."
        }
    ]

    # Make the API call
    response = client.messages.create(
        model=MODEL_NAME,
        max_tokens=1024,
        tools=tools,
        messages=messages
    )

    # Process the response
    if response.stop_reason == "tool_use":
        # Extract the tool use block
        for block in response.content:
            if block.type == "tool_use":
                # Simulate the tool execution - in reality this would call the ledger module
                tool_name = block.name
                tool_input = block.input

                if tool_name == "post":
                    # Simulate posting to ledger and returning an entry id
                    # In production, this would call: ledger.post(acct, cents, reason)
                    entry_id = f"entry_{acct}_{cents}_{abs(hash(reason)) % 10000}"

                    # Create tool result message
                    messages.append({
                        "role": "assistant",
                        "content": response.content
                    })

                    messages.append({
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": block.id,
                                "content": entry_id
                            }
                        ]
                    })

                    # Get the final response with the entry id
                    final_response = client.messages.create(
                        model=MODEL_NAME,
                        max_tokens=1024,
                        tools=tools,
                        messages=messages
                    )

                    # Extract the entry id from the response
                    for final_block in final_response.content:
                        if hasattr(final_block, 'text'):
                            # The entry id should be in the response text
                            return entry_id

    return ""

if __name__ == "__main__":
    # Test the transfer function
    entry_id = transfer("checking", 1000, "Test transfer")
    print(f"Entry ID: {entry_id}")
