from decimal import Decimal, InvalidOperation

def encode_amount(dollars: str) -> str:
    try:
        d = Decimal(dollars)
    except InvalidOperation as exc:
        raise ValueError(f"invalid amount: {dollars}") from exc

    if not d.is_finite():
        raise ValueError(f"invalid amount: {dollars}")

    _, _, exponent = d.as_tuple()
    if exponent < -2:
        raise ValueError(f"amount exceeds two decimal places: {dollars}")

    cents = int(d * 100)
    return str(cents)

