def encode_amount(dollars: str) -> str:
    s = dollars.strip()
    if not s:
        raise ValueError("Empty amount")

    sign = '+'
    if s[0] == '-':
        sign = '-'
        s = s[1:]
    elif s[0] == '+':
        s = s[1:]

    if not s or s == '.':
        return f"{sign}0#0"

    if '.' in s:
        whole, frac = s.split('.', 1)
        whole = whole.lstrip('0') or '0'

        if len(frac) > 2:
            third = int(frac[2]) if frac[2:3] else 0
            first_two = int(frac[:2])
            if third >= 5:
                first_two += 1
            if first_two >= 100:
                first_two = 0
                whole = str(int(whole) + 1)
            total = int(whole) * 100 + first_two
        elif len(frac) == 2:
            total = int(whole) * 100 + int(frac)
        elif len(frac) == 1:
            total = int(whole) * 100 + int(frac) * 10
        else:
            total = int(whole) * 100
    else:
        whole = s.lstrip('0') or '0'
        total = int(whole) * 100

    digits = str(total)
    check = sum(int(ch) for ch in digits) % 10
    return f"{sign}{digits}#{check}"

