from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN


def encode_amount(dollars: str) -> str:
    """
    Encode a dollar amount string as the ledger wire amount: integer cents.

    Examples:
        "12.30" -> "1230"
        "-0.07" -> "-7"
    """
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a str")

    s = dollars.strip()
    if not s:
        raise ValueError("empty amount")

    try:
        value = Decimal(s)
    except InvalidOperation as exc:
        raise ValueError("malformed amount") from exc

    cents = value * Decimal("100")
    if cents != cents.to_integral_value(rounding=ROUND_HALF_EVEN):
        raise ValueError("amount must have no more than two decimal places")

    return str(int(cents))

