import re

_AMOUNT_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d{0,2})?|\.\d{1,2})$")


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    s = dollars.strip()
    if not s or not _AMOUNT_RE.fullmatch(s):
        raise ValueError("malformed money amount")

    negative = s.startswith("-")
    if s[0:1] in "+-":
        s = s[1:]

    if "." in s:
        whole, frac = s.split(".", 1)
    else:
        whole, frac = s, ""

    if whole == "":
        whole = "0"

    frac = (frac + "00")[:2]
    cents = int(whole) * 100 + int(frac)

    if cents == 0:
        return "0"

    return ("-" if negative else "") + str(cents)

