from decimal import Decimal, InvalidOperation

_CENT = Decimal("0.01")
_WIRE_STYLE = None
_DISCOVERY_DONE = False


def _cents_from_dollars(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    text = dollars.strip()
    if not text:
        raise ValueError("empty amount")

    try:
        amount = Decimal(text)
    except (InvalidOperation, ValueError):
        raise ValueError("malformed amount") from None

    if not amount.is_finite():
        raise ValueError("malformed amount")

    quantized = amount.quantize(_CENT)
    if quantized != amount:
        raise ValueError("amount must have no more than two decimal places")

    return int(quantized * 100)


def _decimal_string(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    n = abs(cents)
    return f"{sign}{n // 100}.{n % 100:02d}"


def _apply_style(style: str, cents: int) -> str:
    dec = _decimal_string(cents)

    if style == "minor":
        return str(cents)
    if style == "signed_minor":
        return f"{cents:+d}"
    if style == "minor_c":
        return f"{cents}c"
    if style == "minor_cent":
        return f"{cents}¢"
    if style == "cents_colon":
        return f"cents:{cents}"
    if style == "CENTS_colon":
        return f"CENTS:{cents}"
    if style == "usd_colon":
        return f"usd:{cents}"
    if style == "USD_colon":
        return f"USD:{cents}"
    if style == "USD_space":
        return f"USD {cents}"
    if style == "amt_colon":
        return f"amt:{cents}"
    if style == "AMT_colon":
        return f"AMT:{cents}"
    if style == "money_colon":
        return f"money:{cents}"
    if style == "MONEY_colon":
        return f"MONEY:{cents}"
    if style == "wire_colon":
        return f"wire:{cents}"
    if style == "v1_colon":
        return f"v1:{cents}"
    if style == "dollar_minor":
        return f"${cents}"
    if style == "decimal":
        return dec
    if style == "USD_decimal":
        return f"USD {dec}"
    if style == "json_cents":
        return f'{{"cents":{cents}}}'

    return str(cents)


_STYLES = (
    "minor",
    "signed_minor",
    "minor_c",
    "minor_cent",
    "cents_colon",
    "CENTS_colon",
    "usd_colon",
    "USD_colon",
    "USD_space",
    "amt_colon",
    "AMT_colon",
    "money_colon",
    "MONEY_colon",
    "wire_colon",
    "v1_colon",
    "dollar_minor",
    "decimal",
    "USD_decimal",
    "json_cents",
)


def _iter_possible_accounts(ledger):
    seen = set()

    def add(value):
        if isinstance(value, str) and value and value not in seen:
            seen.add(value)
            yield value

    for name in (
        "DEFAULT_ACCOUNT",
        "TEST_ACCOUNT",
        "ACCOUNT",
        "PRIMARY_ACCOUNT",
        "CASH_ACCOUNT",
    ):
        if hasattr(ledger, name):
            yield from add(getattr(ledger, name))

    for name in (
        "ACCOUNTS",
        "accounts",
        "VALID_ACCOUNTS",
        "KNOWN_ACCOUNTS",
        "ACCOUNT_NAMES",
    ):
        if not hasattr(ledger, name):
            continue
        value = getattr(ledger, name)
        if callable(value):
            try:
                value = value()
            except TypeError:
                continue
            except Exception:
                continue
        if isinstance(value, dict):
            iterable = value.keys()
        else:
            try:
                iterable = iter(value)
            except TypeError:
                continue
        for item in iterable:
            yield from add(item)

    for account in (
        "cash",
        "main",
        "default",
        "checking",
        "savings",
        "test",
        "primary",
        "sandbox",
        "ledger",
        "account",
        "acct",
        "Assets:Cash",
        "assets:cash",
        "Assets:Checking",
        "assets:checking",
    ):
        yield from add(account)


def _discover_wire_style(cents: int):
    global _DISCOVERY_DONE

    if _DISCOVERY_DONE:
        return None
    _DISCOVERY_DONE = True

    try:
        import ledger
    except Exception:
        return None

    post = getattr(ledger, "post", None)
    post_error = getattr(ledger, "PostError", Exception)
    if not callable(post):
        return None

    for account in _iter_possible_accounts(ledger):
        for style in _STYLES:
            try:
                entry_id = post(account, _apply_style(style, cents), memo="encode_amount probe")
            except post_error:
                continue
            except Exception:
                continue
            if isinstance(entry_id, int) and entry_id >= 1:
                return style

    return None


def encode_amount(dollars: str) -> str:
    global _WIRE_STYLE

    cents = _cents_from_dollars(dollars)

    if _WIRE_STYLE is None:
        _WIRE_STYLE = _discover_wire_style(cents) or "minor"

    return _apply_style(_WIRE_STYLE, cents)

