        if isinstance(value, dict):
            iterable = value.keys()
        else:
            try:
                iterable = iter(value)
            except TypeError:
                continue
        for item in iterable:
            yield from add(item)

    for account in (
        "cash",
        "main",
        "default",
        "checking",
        "savings",
        "test",
        "primary",
        "sandbox",
        "ledger",
        "account",
        "acct",
        "Assets:Cash",
        "assets:cash",
