from decimal import Decimal, InvalidOperation
import re

_AMOUNT_RE = re.compile(r"^[+-]?(?:(?:\d+)(?:\.\d{0,2})?|\.\d{1,2})$")


def _malformed_amount():
    try:
        import ledger
        exc = ledger.PostError
    except Exception:
        exc = ValueError
    raise exc("malformed amount")


def encode_amount(dollars: str) -> str:
    if not isinstance(dollars, str):
        _malformed_amount()

    s = dollars.strip()
    if not _AMOUNT_RE.fullmatch(s):
        _malformed_amount()

    try:
        value = Decimal(s)
    except (InvalidOperation, ValueError):
        _malformed_amount()

    cents = int(value * 100)
    return str(cents)

