from __future__ import annotations

import os
from decimal import Decimal, InvalidOperation
from typing import Callable, Iterable, Optional


Encoder = Callable[[int], str]


def _parse_cents(dollars: str) -> int:
    if not isinstance(dollars, str):
        raise TypeError("dollars must be a string")

    text = dollars.strip()
    try:
        value = Decimal(text)
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("malformed dollar amount") from exc

    if not value.is_finite():
        raise ValueError("malformed dollar amount")

    cents = value * Decimal(100)
    if cents != cents.to_integral_value():
        raise ValueError("amount has fractional cents")

    return int(cents)


def _fixed_decimal(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def _candidate_encoders() -> list[Encoder]:
    return [
        lambda c: str(c),
        _fixed_decimal,
        lambda c: f"USD:{c}",
        lambda c: f"usd:{c}",
        lambda c: f"CENTS:{c}",
        lambda c: f"cents:{c}",
        lambda c: f"AMT:{c}",
        lambda c: f"amt:{c}",
        lambda c: f"v1:{c}",
        lambda c: f"money:{c}",
        lambda c: f"USD {_fixed_decimal(c)}",
        lambda c: f"${_fixed_decimal(c)}",
        lambda c: f'{{"cents":{c}}}',
        lambda c: f'{{"amount":"{_fixed_decimal(c)}"}}',
        lambda c: f'{{"amount":"{_fixed_decimal(c)}","currency":"USD"}}',
        lambda c: f"USD|{c}",
        lambda c: f"MONEY|{c}",
    ]


_ENCODERS = _candidate_encoders()
_SELECTED_ENCODER: Optional[Encoder] = None
_LEDGER_IMPORT_FAILED = False


def _strings_from_object(obj: object, depth: int = 0) -> Iterable[str]:
    if depth > 2:
        return

    if isinstance(obj, str):
        yield obj
        return

    if isinstance(obj, dict):
        for key, value in obj.items():
            if isinstance(key, str):
                yield key
            yield from _strings_from_object(value, depth + 1)
        return

    if isinstance(obj, (list, tuple, set, frozenset)):
        for item in obj:
            yield from _strings_from_object(item, depth + 1)


def _candidate_accounts(ledger: object) -> list[str]:
    found: list[str] = []
    seen: set[str] = set()

    def add(value: object) -> None:
        if isinstance(value, str) and value and value not in seen:
            seen.add(value)
            found.append(value)

    for env_name in (
        "LEDGER_ACCOUNT",
        "LEDGER_TEST_ACCOUNT",
        "TEST_LEDGER_ACCOUNT",
        "ACCOUNT",
        "TEST_ACCOUNT",
    ):
        add(os.environ.get(env_name))

    preferred_names = (
        "DEFAULT_ACCOUNT",
        "TEST_ACCOUNT",
        "ACCOUNT",
        "WIRE_ACCOUNT",
        "POST_ACCOUNT",
        "SANDBOX_ACCOUNT",
        "accounts",
        "ACCOUNTS",
        "Accounts",
        "known_accounts",
        "KNOWN_ACCOUNTS",
        "valid_accounts",
        "VALID_ACCOUNTS",
    )

    for name in preferred_names:
        try:
            value = getattr(ledger, name)
        except Exception:
            continue
        for account in _strings_from_object(value):
            add(account)

    try:
        names = dir(ledger)
    except Exception:
        names = ()

    for name in names:
        lower = name.lower()
        if "account" not in lower or name in preferred_names:
            continue
        try:
            value = getattr(ledger, name)
        except Exception:
            continue
        for account in _strings_from_object(value):
            add(account)

    for common in (
        "test",
        "default",
        "main",
        "cash",
        "checking",
        "savings",
        "bank",
        "sandbox",
        "demo",
        "ledger",
        "wire",
        "amount",
        "general",
        "assets",
        "assets:cash",
        "Assets:Cash",
        "income",
        "expense",
        "revenue",
    ):
        add(common)

    return found


def _discover_with_ledger(cents: int) -> Optional[Encoder]:
    global _LEDGER_IMPORT_FAILED

    if _LEDGER_IMPORT_FAILED:
        return None

    try:
        import ledger  # type: ignore
    except Exception:
        _LEDGER_IMPORT_FAILED = True
        return None

    post = getattr(ledger, "post", None)
    post_error = getattr(ledger, "PostError", Exception)
    if post is None:
        return None

    accounts = _candidate_accounts(ledger)
    if not accounts:
        return None

    for account in accounts:
        for encoder in _ENCODERS:
            amount = encoder(cents)
            try:
                post(account, amount, memo="encode_amount format probe")
            except post_error:
                continue
            except Exception:
                continue
            return encoder

    return None


def encode_amount(dollars: str) -> str:
    global _SELECTED_ENCODER

    cents = _parse_cents(dollars)

    if _SELECTED_ENCODER is not None:
        return _SELECTED_ENCODER(cents)

    discovered = _discover_with_ledger(cents)
    if discovered is not None:
        _SELECTED_ENCODER = discovered
        return discovered(cents)

    return str(cents)


__all__ = ["encode_amount"]

